diff --git a/scripts/prepare-public.mjs b/scripts/prepare-public.mjs
index eda477e..dc13613 100644
--- a/scripts/prepare-public.mjs
+++ b/scripts/prepare-public.mjs
@@ -5,7 +5,9 @@ import {readFileSync,writeFileSync,readdirSync,statSync} from 'node:fs';
 import {createHash} from 'node:crypto';
 import path from 'node:path';
 const root=process.cwd(),manifest='data/prepared-public.json';
-const digest=p=>{let bytes=readFileSync(p);if(process.platform==='win32'&&/\.(?:mjs|cjs|js|jsx|ts|tsx|py|json|html|css|md|txt|svg|xml|csv)$/.test(p))bytes=Buffer.from(bytes.toString('utf8').replaceAll('\r\n','\n'));return createHash('sha256').update(bytes).digest('hex')};
+// Text snapshots must have the same digest on Windows and Linux, including
+// tracked CRLF files that Git deliberately retains. Binary assets stay byte-exact.
+const digest=p=>{let bytes=readFileSync(p);if(/\.(?:mjs|cjs|js|jsx|ts|tsx|py|json|html|css|md|txt|svg|xml|csv)$/.test(p))bytes=Buffer.from(bytes.toString('utf8').replaceAll('\r\n','\n'));return createHash('sha256').update(bytes).digest('hex')};
 function files(dir){return readdirSync(dir).flatMap(n=>{const p=path.join(dir,n).replaceAll(String.fromCharCode(92),'/');return statSync(p).isDirectory()?files(p):[p]})}
 const inputs=['scripts/editorial_terms.py','scripts/build-night.py','scripts/editorial_sources.py','scripts/news_images.py','scripts/apply-news-images.py','scripts/build-news.py','config/news-images.json','scripts/deal_tables.py','scripts/build-city.py','scripts/build-home-seniors.py','scripts/home_section_navigation.py','scripts/build-seo.py','scripts/build-editorial.py','data/photo-bank.json','data/photo-bank/categories.json','data/photo-bank/sources.json','config/seo.json','public/news/articles.json','public/news/sections.json','public/night/data.json','public/culture/articles.json','public/future/articles.json','public/city-hub/media.json'];
 let python;for(const executable of ['python','python3']){const probe=spawnSync(executable,['-c','import bs4'],{stdio:'ignore'});if(probe.status===0){python=executable;break}}
